sp_header_footer.client_script:
// Sentinels Hospital Portal Header — Client Script
api.controller = function ($rootScope, $scope, $window, i18n) {

    $scope.logoText = i18n.format(i18n.getMessage('Go to {0} Homepage'), $scope.portal.title);

    $scope.collapse = function () {
        $rootScope.$emit('sp-navbar-collapse');
    };

    // Avatar initialization — sn-avatar requires this object
    $scope.avatarProfile = {
        userID: $scope.user.sys_id,
        name: $scope.user.name,
        initials: $window.NOW.user_initials
    };

    // Set user image if available
    if ($window.NOW.user_avatar) {
        $scope.avatarProfile.userImage = $window.NOW.user_avatar;
    }

    // Show avatar only when user is logged in
    $scope.showAvatar = $scope.user.logged_in;
    $scope.showSMAvatar = $scope.user.logged_in;

    // Login modal handler
    $scope.openLogin = function () {
        $scope.$emit('sp.login');
    };
};

sp_header_footer.css:
// Sentinels Hospital Portal Header Styles
// Dark teal navbar, white text, compact clean design

.navbar {
  transition: 250ms opacity ease-in-out;
  -webkit-transition: 250ms opacity ease-in-out;
  border: 0;
  border-bottom: $sp-navbar-bottom-width solid $sp-navbar-divider-color;
  min-height: 50px;
}

.navbar-fade {
  opacity: 0.4;
}

.navbar-inverse .navbar-toggle {
  border-color: $sp-navbar-toggle-border-color;
}

header[role="banner"],
.nav > li > a {
  max-height: 50px;
}

.nav > li > a {
  font-size: $sp-text-sm;
  font-weight: 500;
  letter-spacing: 0.02em;
  padding-top: $sp-space-4;
  padding-bottom: $sp-space-4;
}

.nav > li > a span.fa {
  margin-left: 0.2rem;
}

.responsive-tablet {
  .nav > li > a {
    padding-right: 0.5rem;
    padding-left: 0.5rem;
  }
}

.navbar-brand {
  max-height: 50px;
  padding: 0;
  padding-bottom: 0.5rem;
  font-size: $sp-text-md;
  font-weight: 600;
  letter-spacing: 0.02em;
}

.navbar-brand img, .navbar-brand span {
  margin-left: $sp-logo-margin-x;
  margin-right: $sp-logo-margin-x;
  margin-top: $sp-logo-margin-y;
  margin-bottom: $sp-logo-margin-y;
  display: block;
  max-height: $sp-logo-max-height;
  max-width: $sp-logo-max-width;
  position: relative;
  top: 50%;
  -webkit-transform: translateY(-50%);
  -ms-transform: translateY(-50%);
  transform: translateY(-50%);
  overflow: hidden;
  width: calc(100% - 3rem);
}

.responsive-tablet {
  .navbar-brand img, .navbar-brand span {
    max-width: $sp-logo-mobile-max-width;
  }
}

nav {
  margin-bottom: 0px;
  border-radius: 0px;

  .toggle-dropdown {
    height: 50px;
  }
}

.navbar-right {
  padding-right: 0px;
  padding-left: 7px;
}

.navbar-nav {
  margin: 0px;
}

.navbar-avatar {
  margin-right: $sp-space-2;
}

// Dropdown menu scrollable when too many items
.scrollable-dropdown {
  max-height: 80vh;
  overflow: auto;
  height: auto;
}

.is-native {
  .scrollable-dropdown {
    max-height: 100vh;
    overflow: scroll;
    height: auto;
  }
}

// CRITICAL: Media query fallbacks for responsive behavior
@media (min-width: 993px) {
  .navbar-right {
    display: flex !important;
    height: auto !important;
  }
}

@media (max-width: 992px) {
  .navbar-toggle {
    display: block;
  }
  .navbar-header {
    float: none;
  }
  .navbar-left, .navbar-right {
    float: none !important;
  }
  .navbar-nav {
    float: none !important;
  }
  .navbar-nav > li {
    float: none;
  }
  .navbar-nav > li > a {
    padding-top: 1rem;
    padding-bottom: 1rem;
  }
}

// Safari alignment fix
.responsive-desktop {
  .navbar-right {
    display: flex !important;
    height: auto !important;
  }
}

.responsive-tablet {
  .navbar-toggle {
    display: block;
  }
  .navbar-header {
    float: none;
  }
  .navbar-left, .navbar-right {
    float: none !important;
  }
  .navbar-nav {
    float: none !important;
  }
  .navbar-nav > li {
    float: none;
  }
  .navbar-nav > li > a {
    padding-top: 1rem;
    padding-bottom: 1rem;
  }
}

// High contrast mode accessibility
@media screen and (-ms-high-contrast: active), (forced-colors: active) {
  .navbar-brand,
  .navbar-nav > li > a,
  .skip-link,
  .btn.btn-primary,
  .btn.btn-danger,
  .navbar-inverse .navbar-toggle {
    &:focus {
      outline-offset: -4px !important;
    }
  }
}

sp_header_footer.script:
// Sentinels Hospital Portal Header — Server Script
// NOTE: No IIFE wrapper — headers execute bare statements

// Portal config
data.login_page = $sp.getValue('login_page');
data.profileBtnMsg = gs.getMessage("User options");
data.toggleMsg = gs.getMessage("Toggle navigation");

// Get menu widget from portal's sp_rectangle_menu field
var menu = $sp.getValue("sp_rectangle_menu");
data.menu = $sp.getWidgetFromInstance(menu);

// Menu flags control visibility and prevent duplication
if (data.menu && data.menu.data) {
    data.menu.data.replace = true; // REQUIRED — prevents menu duplication
    data.hasLogin = false;
    if (data.menu.data.menu && data.menu.data.menu.items) {
        data.hasMenuItems = data.menu.data.menu.items.length > 0;
        for (var i in data.menu.data.menu.items) {
            var item = data.menu.data.menu.items[i];
            if (item.type == 'page' && item.sp_page == data.login_page) {
                data.hasLogin = true;
            }
        }
    }
}

// Current user info
data.userFullName = gs.getUserDisplayName();
data.userSysId = gs.getUserID();
